export type GateType = "kana" | "meaning" | "reading" | "word";

export type KanaItem = {
  char: string;
  romaji: string;
  script: "hiragana" | "katakana";
};

export type GateRow = {
  type: GateType;
  prompt: string;
  options: string[];
  answerIndex: number;
  answer: string;
};

/** A kanji from `src/data/kanji.json`, generated by `npm run data:build`. */
export type KanjiItem = {
  char: string;
  /** Progression level: 2 is the first kanji level, 30 kanji per level. */
  level: number;
  /** KANJIDIC2 school grade: 1–6, or 8 for the rest of Jōyō. */
  grade: number;
  /** Newspaper frequency rank, or null when unranked. */
  freq: number | null;
  /** English glosses; the first is the primary gloss shown on meaning gates. */
  glosses: string[];
  /** Main on'yomi in hiragana. */
  on: string | null;
  /** Main kun'yomi in hiragana, okurigana split out: あ(げる). */
  kun: { base: string; okurigana: string } | null;
  /** Every reading in hiragana (kun'yomi with okurigana), for excluding distractors. */
  readings: string[];
  /** KRADFILE elements, some of them kanji, some radicals such as ⺅. */
  components: string[];
};

/** A katakana loanword from `src/data/loanwords.json`; its level is assigned at load (see words.ts). */
export type WordItem = {
  word: string;
  /** Hand-written English glosses; the first is shown on gates. */
  glosses: string[];
  /** Kanji level (2+) the word joins. */
  level: number;
};

/** SRS record for one item and gate type, keyed `char:type` (e.g. `水:meaning`). */
export type ItemProgress = {
  /** Leitner box 0–5. */
  box: number;
  seen: number;
  correct: number;
  wrong: number;
  /** Epoch ms of the last answer. */
  lastSeen: number;
};

/** Win = the army beat the boss; loss = it died first, or the boss won (a tie is a loss). */
export type RunStats = { runs: number; wins: number; losses: number };

/** Everything persisted: the one contract for storage, run building and sync. */
export type Progress = {
  version: 1;
  /** 0 hiragana, 1 katakana, 2+ kanji levels. */
  unlockedLevel: number;
  /** Only items that have a record; a missing key is a new item. */
  items: Record<string, ItemProgress>;
  stats: RunStats;
};
